async function createTodo(title) {
  const res = await fetch(`${BASE_URL}/api/todos`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ title })
  });
  assert.strictEqual(res.status, 201);
  return res.json();
}

async function listTodos() {
  const res = await fetch(`${BASE_URL}/api/todos`);
  assert.strictEqual(res.status, 200);
  return res.json();
}

test('DELETE /api/todos/:id removes an existing todo with 204 and empty body', async () => {
  const target = await createTodo('DELETE target');
  const other = await createTodo('DELETE bystander');
  const before = await listTodos();

  const res = await fetch(`${BASE_URL}/api/todos/${target.id}`, { method: 'DELETE' });
  assert.strictEqual(res.status, 204);
  assert.strictEqual(await res.text(), '');

  const after = await listTodos();
  assert.ok(!after.some(t => t.id === target.id));
  assert.deepStrictEqual(after, before.filter(t => t.id !== target.id));
  assert.deepStrictEqual(after.find(t => t.id === other.id), other);
});

test('DELETE /api/todos/:id returns 404 when deleting the same id again', async () => {
  const target = await createTodo('DELETE twice');
  const first = await fetch(`${BASE_URL}/api/todos/${target.id}`, { method: 'DELETE' });
  assert.strictEqual(first.status, 204);

  const before = await listTodos();
  const second = await fetch(`${BASE_URL}/api/todos/${target.id}`, { method: 'DELETE' });
  assert.strictEqual(second.status, 404);
  assert.deepStrictEqual(await listTodos(), before);
});

test('DELETE /api/todos/:id returns 404 for a valid id that does not exist', async () => {
  const before = await listTodos();
  const res = await fetch(`${BASE_URL}/api/todos/9007199254740991`, { method: 'DELETE' });
  assert.strictEqual(res.status, 404);
  assert.deepStrictEqual(await listTodos(), before);
});

test('DELETE /api/todos/:id returns 400 for invalid ids and changes nothing', async () => {
  await createTodo('DELETE invalid-id guard');
  const before = await listTodos();
  const invalidIds = ['abc', '1abc', '1.5', '0', '-1', '9007199254740992', '+1', '1e2', '00', '%201'];
  for (const id of invalidIds) {
    const res = await fetch(`${BASE_URL}/api/todos/${id}`, { method: 'DELETE' });
    assert.strictEqual(res.status, 400, `id "${id}" should be rejected`);
  }
  assert.deepStrictEqual(await listTodos(), before);
});
EOF
